-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["541a7149ff6762a1"] = { "Caro diario,\n\ndevo star invecchiando. Mi ero completamente dimenticato che ti stavo raccontando di Narain e del suo inganno. Comunque, quando ho visto un'esca travestita da Narain invece di Narain, mi sono arrabbiato così tanto che ho ordinato a ⟦Number Two=Numero Due⟧ di distruggere quell'idiota!\n\nSono salito sulla mia macchina volante e ho cominciato a fare a pezzi il suo prezioso, stupido, idiotissimo libro sul draconico. Che sbruffone! Chi lo legge, il draconico? Lo odio da morire!", "." },
  ["5434746d7c0db3e4"] = { "Alexstrasza, la Protettrice della Vita, pose una singola ghianda incantata nel cuore del ⟦Well of Eternity=Pozzo dell'Eternità⟧. La ghianda, attivata dalle potenti acque magiche, prese vita trasformandosi in un albero colossale. Le radici del possente albero crescevano dalle acque del Pozzo, e la sua chioma verdeggiante sembrava sfiorare la volta del cielo.", "." },
  ["54811868b74983a0"] = { "--Giorno 6--\n\nLe condizioni di Heralath peggiorano.\n\nOggi ha aperto gli occhi una sola volta. Ha parlato con un'angoscia sofferta, ma il suo messaggio era chiaro. Se riuscissi a sfuggire alla mia sorte qui nelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧, dovrei far sapere a Falfindel Waywarder, a Thalanaar, che ⟦Charlga Razorflank=Charlga Fiancospino⟧ sta radunando seguaci nelle ⟦Barrens=Savane⟧ meridionali. Il suo potere cresce di giorno in giorno. La Megera va fermata prima che la piaga della corruzione possa diffondersi dalle Gallerie.", "." },
  ["54d38bcf4baba975"] = { "Per quanto i sintomi fossero chiari, Antonidas non riuscì a trovare una cura per la condizione in cui versavano gli orchi. Inoltre, molti dei suoi colleghi maghi, e anche alcuni importanti capi dell'⟦Alliance=Alleanza⟧, sostenevano che cercare una cura per gli orchi sarebbe stata un'impresa imprudente. Rimasto a riflettere sulla misteriosa condizione degli orchi, Antonidas concluse che la loro cura avrebbe dovuto essere spirituale.", "." },
  ["54da9afb56f6615f"] = { "A pochi giorni dal mio arrivo mi sono ritrovato a fare da precettore ai bambini delle fattorie vicine. Le lezioni sono andate così bene che il sindaco della città mi ha incaricato di dirigere una scuola, e sono già iniziati i lavori per un edificio scolastico nuovo di zecca! Da ⟦Silverpine=Pinargento⟧ a ⟦Stormwind=Roccavento⟧ e ora a ⟦Moonbrook=Rivoluna⟧: chi avrebbe mai detto che avrei visto tanta parte di Azeroth!\n\nCon i più cordiali saluti,\n\n⟦Stalvan Mistmantle=Stalvan Foscomanto⟧", "." },
  ["54ea0868fe577940"] = { "A detta di tutti, gli eroi riuscirono a distruggere il portale e a salvare Azeroth, ma resta ancora da vedere se siano sfuggiti o meno all'agonia di Draenor.", "." },
})
